using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.IO;

// Mechanical thumbnail encoding only. All illustration content is generated by
// image_gen; this tool preserves its composition and writes a compact local PNG.
class InteractionArtThumbnail
{
    static void Main(string[] args)
    {
        foreach (string row in File.ReadAllLines(args[0]))
        {
            if (row.Length == 0) continue;
            string[] files = row.Split('\t');
            string target = Path.GetFullPath(files[1]);
            if (File.Exists(target)) continue;
            Directory.CreateDirectory(Path.GetDirectoryName(target));
            using (var input = Image.FromFile(files[0]))
            using (var result = new Bitmap(256, 256, PixelFormat.Format32bppArgb))
            using (var graphics = Graphics.FromImage(result))
            {
                Rectangle source = new Rectangle(0, 0, input.Width, input.Height);
                if (files.Length == 6)
                {
                    int columns = int.Parse(files[2]), rows = int.Parse(files[3]);
                    int column = int.Parse(files[4]), rowIndex = int.Parse(files[5]);
                    double ratio = (input.Width / (double)columns) / (input.Height / (double)rows);
                    if (ratio < .94 || ratio > 1.06) throw new Exception("Atlas aspect ratio does not match square cells: " + files[0]);
                    int left = (int)Math.Round(column * input.Width / (double)columns);
                    int top = (int)Math.Round(rowIndex * input.Height / (double)rows);
                    int right = (int)Math.Round((column + 1) * input.Width / (double)columns);
                    int bottom = (int)Math.Round((rowIndex + 1) * input.Height / (double)rows);
                    int inset = Math.Max(2, (int)Math.Round(Math.Min(right - left, bottom - top) * .015));
                    source = new Rectangle(left + inset, top + inset, right - left - 2 * inset, bottom - top - 2 * inset);
                }
                else if (input.Width != input.Height) throw new Exception("Square illustration expected: " + files[0]);
                graphics.CompositingQuality = CompositingQuality.HighQuality;
                graphics.InterpolationMode = InterpolationMode.HighQualityBicubic;
                graphics.SmoothingMode = SmoothingMode.HighQuality;
                graphics.PixelOffsetMode = PixelOffsetMode.HighQuality;
                using (var attributes = new ImageAttributes())
                {
                    attributes.SetWrapMode(WrapMode.TileFlipXY);
                    graphics.DrawImage(input, new Rectangle(0, 0, 256, 256), source.X, source.Y, source.Width, source.Height, GraphicsUnit.Pixel, attributes);
                }
                result.Save(target, ImageFormat.Png);
            }
        }
    }
}
